 "content": "def transform(grid):
    """Restore diagonal-symmetry masks, using the repeated row reflection too."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def orbit(r, c):
        seen = {(r, c)}
        todo = [(r, c)]
        while todo:
            a, b = todo.pop()
            candidates = [(b, a)]  # main-diagonal reflection
            if 2 <= a <= 29 and 31 - a < h:
                candidates.append((31 - a, b))  # horizontal reflection
            for x, y in candidates:
                if 0 <= x < h and 0 <= y < w and (x, y) not in seen:
                    seen.add((x, y))
                    todo.append((x, y))
        return seen

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                sources = [(a, b) for a, b in orbit(r, c) if grid[a][b] != 6]
                if sources:
                    out[r][c] = grid[sources[0][0]][sources[0][1]]
    return out
